const raw    = $('Resolve Gap Webhook').first().json;
const body   = raw.body || raw;
const config = $('Configuration').first().json;

const question     = body.question      || '';
const answer       = body.answer        || '';
const theme        = body.theme         || 'knowledge_gap';
const gap_id       = body.gap_id        || '';
const ticket_id    = body.ticket_id     || '';
const customer_name = body.customer_name || 'Customer';
const channel      = body.channel       || 'email';

if (!question || !answer) throw new Error('Missing question or answer in webhook payload');

const firstName = customer_name.split(' ')[0] || 'there';

const systemPrompt = [
  'You are a knowledge base editor AND customer service writer for Boldr, a Singapore-based watch micro-brand.',
  'Given a customer question and a CS agent answer, produce two outputs:',
  '1. A clean KB entry (question + answer formatted for internal knowledge base)',
  '2. A ready-to-send customer reply (warm, branded, addressed to the customer by first name)',
  '',
  'Rules:',
  '- KB question: concise and generalisable, remove personal details.',
  '- KB answer: factual, under 80 words, brand voice.',
  '- Customer reply: Friendly and professional, addressed to ' + firstName + '.',
  '  Vary the opening naturally — do not use the same phrase every time.',
  '  Get to the answer quickly. No filler. No padding.',
  '  NEVER start with Great question! or use Dear Sir/Madam.',
  '  NEVER promise timelines you cannot guarantee.',
  '- Do NOT invent any facts beyond what the agent provided.',
  '',
  'Respond ONLY with valid JSON — no markdown, no extra text:',
  '{',
  '  "question": "Clean KB question",',
  '  "answer": "KB answer (factual, concise)",',
  '  "theme": "one of: materials_safety, customisation, servicing, shipping, product_specs, sustainability, pricing, knowledge_gap",',
  '  "draft_reply": "Full customer-facing reply, addressed to ' + firstName + '"',
  '}'
].join('\n');

const userMessage = [
  'Customer: ' + customer_name,
  'Channel: '  + channel,
  'Question: ' + question,
  'CS answer: ' + answer,
  'Theme: '    + theme
].join('\n');

return [{
  json: {
    gap_id, ticket_id, customer_name, channel,
    original_question: question,
    original_answer:   answer,
    theme,
    supabase_url: config.SUPABASE_URL,
    supabase_key: config.SUPABASE_KEY,
    request_body: {
      model:      config.QWEN_MODEL,
      max_tokens: 600,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user',   content: userMessage  }
      ]
    }
  }
}];

const response = $input.first();
const orig     = $('Build Qwen KB Request').first().json;
const rawText  = response.json.choices?.[0]?.message?.content || '';

const cleaned = rawText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let result;
try {
  result = JSON.parse(cleaned);
} catch (e) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try { result = JSON.parse(match[0]); } catch (e2) { result = null; }
  }
}

if (!result) {
  result = {
    question:    orig.original_question,
    answer:      orig.original_answer,
    theme:       orig.theme,
    draft_reply: null
  };
}

const approvedAt = new Date().toISOString();
console.log('KB entry formatted — Q: ' + result.question);

return [{
  json: {
    gap_id:        orig.gap_id,
    ticket_id:     orig.ticket_id,
    customer_name: orig.customer_name,
    channel:       orig.channel,
    question:      result.question    || orig.original_question,
    answer:        result.answer      || orig.original_answer,
    theme:         result.theme       || orig.theme,
    draft_reply:   result.draft_reply || null,
    approved_at:   approvedAt,
    supabase_url:  orig.supabase_url,
    supabase_key:  orig.supabase_key
  }
}];
